// The Google Sheets node emits one item per row plus a row_number field.
// Keep every row that is marked Featured and has not been compiled yet, in
// sheet order, up to maxQuotes. row_number is what the write-back matches on.
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json);

const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const truthy = (v) => {
  const s = String(v == null ? '' : v).trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === 'y' || s === '1' || s === 'x' || s === '✓' || s === 'featured';
};
const text = (v) => String(v == null ? '' : v).trim();

const maxQuotes = Math.max(2, Math.min(12, Number(cfg.maxQuotes) || 5));
const minQuotes = Math.max(2, Math.min(maxQuotes, Number(cfg.minQuotes) || 2));

const picked = [];
const skipped = { notFeatured: 0, alreadyCompiled: 0, noQuote: 0 };

for (const r of rows) {
  if (!truthy(r.Featured)) { skipped.notFeatured += 1; continue; }
  if (!isEmpty(r.Status)) { skipped.alreadyCompiled += 1; continue; }
  const quote = text(r.Quote);
  if (!quote) { skipped.noQuote += 1; continue; }
  picked.push({
    quote,
    author: text(r.Author),
    role: text(r.Role),
    company: text(r.Company),
    rating: text(r.Rating),
    rowNumber: r.row_number,
    recordId: '',
  });
  if (picked.length >= maxQuotes) break;
}

if (picked.length < minQuotes) {
  return [{ json: { found: false, source: 'sheet', picked: picked.length, minQuotes, checked: rows.length, skipped } }];
}

return [{ json: { found: true, source: 'sheet', testimonials: picked, checked: rows.length, skipped } }];

// Same filter as the sheet path, against Airtable's { records: [{ id, fields }] }.
// Field names must match the sheet header exactly: Quote, Author, Role,
// Company, Rating, Featured, Status. Airtable has no row numbers, so the sheet
// write-back is skipped in this mode (see the Run summary node).
const cfg = $('Config').first().json;
const res = $input.first().json;
const status = Number(res && res.statusCode);
const body = (res && res.body) || {};

if (!Number.isFinite(status) || status === 0) {
  throw new Error('Airtable did not answer. Check airtableBaseId / airtableTable in Config and that the Bearer Auth credential holds a personal access token.');
}
if (status >= 400) {
  const e = body && body.error;
  const msg = e ? (e.message || e.type || JSON.stringify(e)) : JSON.stringify(body).slice(0, 300);
  throw new Error('Airtable answered HTTP ' + status + ': ' + msg);
}

const records = Array.isArray(body.records) ? body.records : [];
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const truthy = (v) => {
  if (v === true) return true;
  const s = String(v == null ? '' : v).trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === 'y' || s === '1' || s === 'x' || s === '✓' || s === 'featured';
};
const text = (v) => (Array.isArray(v) ? v.join(' ') : String(v == null ? '' : v)).trim();

const maxQuotes = Math.max(2, Math.min(12, Number(cfg.maxQuotes) || 5));
const minQuotes = Math.max(2, Math.min(maxQuotes, Number(cfg.minQuotes) || 2));

const picked = [];
const skipped = { notFeatured: 0, alreadyCompiled: 0, noQuote: 0 };

for (const rec of records) {
  const f = (rec && rec.fields) || {};
  if (!truthy(f.Featured)) { skipped.notFeatured += 1; continue; }
  if (!isEmpty(f.Status)) { skipped.alreadyCompiled += 1; continue; }
  const quote = text(f.Quote);
  if (!quote) { skipped.noQuote += 1; continue; }
  picked.push({
    quote,
    author: text(f.Author),
    role: text(f.Role),
    company: text(f.Company),
    rating: text(f.Rating),
    rowNumber: 0,
    recordId: String(rec.id || ''),
  });
  if (picked.length >= maxQuotes) break;
}

if (picked.length < minQuotes) {
  return [{ json: { found: false, source: 'airtable', picked: picked.length, minQuotes, checked: records.length, skipped } }];
}

return [{ json: { found: true, source: 'airtable', testimonials: picked, checked: records.length, skipped } }];

// Fewer than minQuotes rows are waiting. A compilation of one quote is not a
// compilation, so this is a normal, successful outcome — not an error.
const picked = $input.first().json;
return [{
  json: {
    rendered: false,
    reason: 'Found ' + picked.picked + ' testimonial(s) marked Featured with an empty Status; this compilation needs at least ' + picked.minQuotes + '.',
    source: picked.source,
    rowsChecked: picked.checked,
    skipped: picked.skipped,
    fix: 'Tick Featured on more rows (and clear their Status), or lower minQuotes in Config.',
  },
}];

// Adds the month label and hands the builder one tidy item. The label is
// DATA, not a design decision — monthLabelOverride pins it, monthLabelMode
// picks the current month (default) or the one that just ended, which is what
// you usually want from a run on the 1st.
const cfg = $('Config').first().json;
const picked = $input.first().json;

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

let monthLabel = String(cfg.monthLabelOverride || '').trim();
if (!monthLabel) {
  const now = new Date();
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  if (String(cfg.monthLabelMode || 'current').toLowerCase() === 'previous') {
    d.setUTCMonth(d.getUTCMonth() - 1);
  }
  monthLabel = MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}

const list = Array.isArray(picked.testimonials) ? picked.testimonials : [];

return [{
  json: {
    found: true,
    source: picked.source,
    monthLabel,
    testimonials: list.map((t) => ({
      quote: t.quote,
      author: t.author,
      role: t.role,
      company: t.company,
      rating: t.rating,
    })),
    rows: list.map((t) => ({
      rowNumber: t.rowNumber || 0,
      recordId: t.recordId || '',
      author: t.author,
    })),
  },
}];

// The music bed is optional. An unreachable URL, an HTTP error or a file over
// the plan's audio cap renders the compilation WITHOUT music instead of failing
// the run — a silent testimonial reel still sells, a failed run does not.
const cfg = $('Config').first().json;
const prepared = $('Prepare compilation').first().json;
const res = $input.first().json;

const maxBytes = Number(cfg.maxMusicBytes) || 5242880;
const url = String(cfg.musicUrl || '').trim();

let musicUrl = url;
let reason = null;
let bytes = null;

if (!url) {
  musicUrl = '';
  reason = 'musicUrl is empty in Config';
} else {
  const status = Number(res && res.statusCode);
  const headers = (res && res.headers) || {};
  const len = Number(headers['content-length'] || headers['Content-Length'] || 0);
  bytes = Number.isFinite(len) && len > 0 ? len : null;
  if (!Number.isFinite(status) || status === 0) {
    musicUrl = '';
    reason = 'the music URL was unreachable';
  } else if (status >= 400) {
    musicUrl = '';
    reason = 'the music URL answered HTTP ' + status;
  } else if (bytes && bytes > maxBytes) {
    musicUrl = '';
    reason = 'the music file is ' + Math.round(bytes / 1024) + ' KB, over the ' + Math.round(maxBytes / 1024) + ' KB cap';
  }
}

return [{ json: { ...prepared, musicUrl, musicBytes: bytes, musicSkippedReason: reason } }];

// === buildProject — identical to the frame-reviewed standalone builder ===
// Emits a Zvid TEMPLATE project: ONE testimonial scene carrying `iterate`,
// plus the data in `variables`. Zvid resolves `iterate` into one scene per
// testimonial before validation, so the scene count follows the sheet and the
// payload stays the same size whether there are two quotes or twelve.
function buildProject(config, data) {
  const cfg = config || {};

  // Sheet / Airtable text is untrusted twice over: it lands inside HTML, and
  // it lands inside a template that resolves {{placeholders}}. Collapse
  // whitespace, defuse braces, then HTML-escape at the variable boundary.
  const clean = (v) => {
    let s = String(v == null ? '' : v).replace(/\s+/g, ' ');
    // Collapse repeatedly: "{{{{" would otherwise fold back into "{{" and
    // reopen a placeholder. Each pass strictly shortens the string.
    while (s.indexOf('{{') !== -1 || s.indexOf('}}') !== -1) {
      s = s.replace(/\{\{/g, '{').replace(/\}\}/g, '}');
    }
    return s.trim();
  };
  const esc = (s) =>
    String(s).replace(
      /[&<>"']/g,
      (c) =>
        ({
          '&': '&amp;',
          '<': '&lt;',
          '>': '&gt;',
          '"': '&quot;',
          "'": '&#39;',
        })[c]
    );
  const round = (n) => Math.round(n * 100) / 100;
  const httpUrl = (u) => (/^https?:\/\//i.test(u) ? u : '');

  // ---- config ------------------------------------------------------------
  const brandName = clean(cfg.brandName) || 'Your brand';
  const kickerText = (clean(cfg.kickerText) || 'CUSTOMER STORIES').toUpperCase().slice(0, 38);
  const introTitle = clean(cfg.introTitle) || 'What our customers say';
  const ctaText = clean(cfg.ctaText) || 'Join them';
  const ctaUrl = clean(cfg.ctaUrl);
  const logoUrl = httpUrl(clean(cfg.logoUrl));
  const verifiedLabel = (clean(cfg.verifiedLabel) || 'VERIFIED CUSTOMER').toUpperCase();
  const quoteFont = clean(cfg.quoteFont) || 'Playfair Display';
  const uiFont = clean(cfg.uiFont) || 'Outfit';
  const paper = clean(cfg.paperColor) || '#F4F1EA';
  const ink = clean(cfg.inkColor) || '#12161B';
  const accent = clean(cfg.accentColor) || '#2F6155';
  const accentDark = clean(cfg.accentOnDark) || '#84C6B2';
  const star = clean(cfg.starColor) || '#9A6B14';
  const starDark = clean(cfg.starOnDark) || '#E8B94B';
  const mutedPaper = clean(cfg.mutedOnPaper) || '#5C5548';
  const mutedInk = clean(cfg.mutedOnInk) || '#96A1AC';
  const maxQuotes = Math.max(2, Math.min(12, Number(cfg.maxQuotes) || 5));
  const maxQuoteChars = Math.max(80, Math.min(400, Number(cfg.maxQuoteChars) || 260));

  // ---- data --------------------------------------------------------------
  const list = Array.isArray(data.testimonials) ? data.testimonials.slice(0, maxQuotes) : [];
  if (list.length < 2) {
    throw new Error(
      'A compilation needs at least 2 testimonials, got ' +
        list.length +
        '. Mark more rows Featured (and leave their Status empty).'
    );
  }

  const monthLabel = clean(data.monthLabel);

  // ---- geometry ----------------------------------------------------------
  // 1080x1080. Everything below the quote sits on a fixed baseline grid, so
  // the cut from one testimonial to the next never moves the author block —
  // only the quote itself re-flows.
  const MARGIN = 96;
  const BOX = 888; // 1080 - 2*96
  const QUOTE_TOP = 330;
  const QUOTE_BOTTOM = 748;
  const QUOTE_H = QUOTE_BOTTOM - QUOTE_TOP;
  const BADGE_Y = 780;
  const RULE_Y = 860;
  const RING_CY = 940;
  const TD = 0.55; // testimonial -> testimonial transition

  // Greedy word-wrap estimate, calibrated the same way the quote-reel template
  // was: Playfair Display at 600 weight averages ~0.52em per glyph.
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) {
        used = need;
        continue;
      }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };

  // Pick the largest size whose wrapped block still fits the quote window, so
  // a 40-character quote sets big and a 260-character one steps down instead
  // of running into the star row.
  const fitBlock = (text, sizes, boxPx, avgEm, lineHeight, maxH) => {
    let chosen = null;
    for (const px of sizes) {
      const lines = wrapLines(text, px, boxPx, avgEm);
      const height = Math.round(lines * px * lineHeight);
      chosen = { size: px, lines, height };
      if (height <= maxH) return chosen;
    }
    return chosen;
  };

  // Long quotes are trimmed on a word boundary rather than clipped on screen.
  const truncate = (text, max) => {
    if (text.length <= max) return { text, truncated: false };
    const cut = text.slice(0, max);
    const at = cut.lastIndexOf(' ');
    return {
      text: (at > max * 0.6 ? cut.slice(0, at) : cut).replace(/[,;:.–—-]+$/, '') + '…',
      truncated: true,
    };
  };

  const initialsOf = (name) => {
    const parts = String(name)
      .split(' ')
      .filter((p) => /[A-Za-z0-9]/.test(p));
    const letters = parts
      .slice(0, 2)
      .map((p) => p.replace(/[^A-Za-z0-9]/g, '').charAt(0))
      .join('');
    return (letters || String(name).trim().charAt(0) || 'A').toUpperCase();
  };

  const pad2 = (n) => (n < 10 ? '0' + n : String(n));

  // Letterspaced caps blow past their box long before a normal word-wrap
  // estimate says they should, so tracked labels get their own ramp: pick the
  // first (size, tracking) pair whose measured run fits the box on one line.
  const trackedFit = (text, boxPx, steps) => {
    const n = String(text).length;
    for (const s of steps) {
      if (n * (s[0] * 0.62 + s[1]) <= boxPx) return { size: s[0], tracking: s[1] };
    }
    const last = steps[steps.length - 1];
    return { size: last[0], tracking: last[1] };
  };
  const plainFit = (text, boxPx, sizes, em) => {
    const n = String(text).length;
    for (const px of sizes) {
      if (n * px * em <= boxPx) return px;
    }
    return sizes[sizes.length - 1];
  };

  // A five-point star as pure geometry — no font is involved, so the row looks
  // identical on every renderer.
  const starPath = (cx, cy, r) => {
    const pts = [];
    for (let i = 0; i < 10; i++) {
      const rad = i % 2 === 0 ? r : r * 0.42;
      const a = (Math.PI / 5) * i - Math.PI / 2;
      pts.push((cx + rad * Math.cos(a)).toFixed(1) + ' ' + (cy + rad * Math.sin(a)).toFixed(1));
    }
    return 'M ' + pts.join(' L ') + ' Z';
  };

  const starsSvg = (filled, color) => {
    let out =
      "<svg width='212' height='40' viewBox='0 0 212 40' xmlns='http://www.w3.org/2000/svg'>";
    for (let i = 0; i < 5; i++) {
      out +=
        "<path d='" +
        starPath(18 + i * 44, 20, 18) +
        "' fill='" +
        color +
        "' fill-opacity='" +
        (i < filled ? '1' : '0.22') +
        "'/>";
    }
    return out + '</svg>';
  };

  // Chapter rail across the top frame edge: one segment per testimonial,
  // filled up to the current one. Baked per scene, so it is deterministic.
  const railSvg = (index, total, fillColor, lineColor) => {
    const gap = 8;
    const seg = (1000 - (total - 1) * gap) / total;
    let out = '';
    for (let k = 0; k < total; k++) {
      const x = 40 + k * (seg + gap);
      // 4px tall and centred on the frame's 1.4px top stroke, so the rail
      // covers the hairline instead of half-blending with it.
      out +=
        "<rect x='" +
        x.toFixed(1) +
        "' y='38' width='" +
        seg.toFixed(1) +
        "' height='4' fill='" +
        (k <= index ? fillColor : lineColor) +
        "' fill-opacity='" +
        (k <= index ? '1' : '0.18') +
        "'/>";
    }
    return out;
  };

  const FRAME = "<rect x='40' y='40' width='1000' height='1000' fill='none' ";

  // The marginal rule beside the quote: it tracks the quote block, so a short
  // testimonial and a long one both read as "this bit is the quotation".
  const markSvg = (color, y, h) =>
    "<rect x='38' y='" + y + "' width='5' height='" + h + "' fill='" + color + "'/>";

  // Treatment A — warm paper card, accent tick on the left frame edge.
  const panelPaper = (index, total, markY, markH) =>
    "<svg width='1080' height='1080' viewBox='0 0 1080 1080' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><linearGradient id='tcpa' x1='0' y1='0' x2='0.55' y2='1'>" +
    "<stop offset='0' stop-color='#FCFAF6'/><stop offset='1' stop-color='#E9E3D5'/></linearGradient>" +
    "<radialGradient id='tcpg' cx='0.06' cy='0.04' r='0.75'>" +
    "<stop offset='0' stop-color='" +
    accent +
    "' stop-opacity='0.13'/>" +
    "<stop offset='1' stop-color='" +
    accent +
    "' stop-opacity='0'/></radialGradient></defs>" +
    "<rect width='1080' height='1080' fill='url(#tcpa)'/>" +
    "<rect width='1080' height='1080' fill='url(#tcpg)'/>" +
    FRAME +
    "stroke='" +
    ink +
    "' stroke-opacity='0.14' stroke-width='1.4'/>" +
    railSvg(index, total, accent, ink) +
    markSvg(accent, markY, markH) +
    "<circle cx='138' cy='" +
    RING_CY +
    "' r='42' fill='none' stroke='" +
    accent +
    "' stroke-opacity='0.5' stroke-width='2'/>" +
    '</svg>';

  // Treatment B — deep ink card, accent corner wedge bottom-right.
  const panelInk = (index, total, markY, markH) =>
    "<svg width='1080' height='1080' viewBox='0 0 1080 1080' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><linearGradient id='tcia' x1='0' y1='0' x2='0.5' y2='1'>" +
    "<stop offset='0' stop-color='#1B242B'/><stop offset='1' stop-color='#0C1013'/></linearGradient>" +
    "<radialGradient id='tcig' cx='0.94' cy='0.92' r='0.8'>" +
    "<stop offset='0' stop-color='" +
    accentDark +
    "' stop-opacity='0.17'/>" +
    "<stop offset='1' stop-color='" +
    accentDark +
    "' stop-opacity='0'/></radialGradient></defs>" +
    "<rect width='1080' height='1080' fill='url(#tcia)'/>" +
    "<rect width='1080' height='1080' fill='url(#tcig)'/>" +
    "<path d='M 1040 700 L 1040 1040 L 700 1040 Z' fill='" +
    accentDark +
    "' fill-opacity='0.08'/>" +
    FRAME +
    "stroke='" +
    paper +
    "' stroke-opacity='0.16' stroke-width='1.4'/>" +
    railSvg(index, total, accentDark, paper) +
    markSvg(accentDark, markY, markH) +
    "<circle cx='138' cy='" +
    RING_CY +
    "' r='42' fill='none' stroke='" +
    accentDark +
    "' stroke-opacity='0.5' stroke-width='2'/>" +
    '</svg>';

  // Intro / outro share one title panel so the film is bookended.
  const panelTitle =
    "<svg width='1080' height='1080' viewBox='0 0 1080 1080' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><linearGradient id='tcta' x1='0.1' y1='0' x2='0.9' y2='1'>" +
    "<stop offset='0' stop-color='#1D272E'/><stop offset='1' stop-color='#0B0F12'/></linearGradient>" +
    "<radialGradient id='tctg' cx='0.5' cy='0.4' r='0.62'>" +
    "<stop offset='0' stop-color='" +
    accentDark +
    "' stop-opacity='0.2'/>" +
    "<stop offset='1' stop-color='" +
    accentDark +
    "' stop-opacity='0'/></radialGradient></defs>" +
    "<rect width='1080' height='1080' fill='url(#tcta)'/>" +
    "<rect width='1080' height='1080' fill='url(#tctg)'/>" +
    FRAME +
    "stroke='" +
    paper +
    "' stroke-opacity='0.16' stroke-width='1.4'/>" +
    "<circle cx='540' cy='540' r='424' fill='none' stroke='" +
    accentDark +
    "' stroke-opacity='0.12' stroke-width='1.4'/>" +
    '</svg>';

  const ruleSvg = (color) =>
    "<svg width='120' height='3' viewBox='0 0 120 3' xmlns='http://www.w3.org/2000/svg'>" +
    "<rect width='120' height='3' fill='" +
    color +
    "'/></svg>";

  const dividerSvg = (color, opacity) =>
    "<svg width='" +
    BOX +
    "' height='2' viewBox='0 0 " +
    BOX +
    " 2' xmlns='http://www.w3.org/2000/svg'>" +
    "<rect width='" +
    BOX +
    "' height='2' fill='" +
    color +
    "' fill-opacity='" +
    opacity +
    "'/></svg>";

  // ---- per-testimonial variables ----------------------------------------
  const total = list.length;
  const items = [];
  let truncatedCount = 0;
  let starredCount = 0;

  list.forEach((raw, i) => {
    const rawQuote = clean(raw.quote);
    const author = clean(raw.author) || 'Anonymous';
    if (!rawQuote) {
      throw new Error(
        'Testimonial ' + (i + 1) + ' (' + author + ') has no quote text — fill its Quote cell.'
      );
    }
    const t = truncate(rawQuote, maxQuoteChars);
    if (t.truncated) truncatedCount += 1;
    const quote = t.text;

    const role = clean(raw.role);
    const company = clean(raw.company);
    // The author block is optically centred on the ring, so the role/company
    // line is capped at two lines — past that it is trimmed on a word boundary.
    const metaRaw = [role, company].filter(Boolean).join(' · ') || 'Customer';
    const metaLine = truncate(metaRaw, 118).text;
    const metaLines = Math.min(2, wrapLines(metaLine, 25, 760, 0.5));
    const authorName = truncate(author, 44).text;
    const authorSize = plainFit(authorName, 760, [38, 34, 30, 27], 0.55);
    const authorY = Math.round(
      RING_CY - (Math.round(authorSize * 1.15) + 8 + metaLines * 33) / 2
    );

    const ratingNum = Number(String(raw.rating == null ? '' : raw.rating).replace(/[^0-9.]/g, ''));
    const filled =
      Number.isFinite(ratingNum) && ratingNum >= 1 ? Math.min(5, Math.round(ratingNum)) : 0;
    const hasRating = filled >= 1;
    if (hasRating) starredCount += 1;

    const dark = i % 2 === 1;

    const qLen = quote.length;
    const fit = fitBlock(quote, [66, 60, 54, 48, 43, 38, 34], BOX, 0.52, 1.3, QUOTE_H);
    const quoteY = Math.round(QUOTE_TOP + Math.max(0, (QUOTE_H - fit.height) / 2));
    // The opening glyph and the marginal rule travel with the quote block so
    // the three read as one group at every quote length.
    const glyphY = Math.max(150, quoteY - 105);
    const markH = Math.max(140, fit.height);

    // Reading time, floored so a two-word quote still lands, capped so one
    // long testimonial cannot swallow the compilation.
    const seconds = round(Math.min(9.5, Math.max(5, 3.4 + qLen * 0.03)));

    items.push({
      quote: esc(quote),
      quoteSize: fit.size + 'px',
      quoteY,
      glyphY,
      author: esc(authorName),
      metaLine: esc(metaLine),
      authorSize: authorSize + 'px',
      authorY,
      initials: esc(initialsOf(author)),
      counter: pad2(i + 1) + ' / ' + pad2(total),
      hasRating,
      noRating: !hasRating,
      rating: filled,
      duration: round(seconds + TD),
      seconds,
      sceneBg: dark ? ink : paper,
      textColor: dark ? paper : ink,
      mutedColor: dark ? mutedInk : mutedPaper,
      accentColor: dark ? accentDark : accent,
      panelSvg: dark
        ? panelInk(i, total, quoteY, markH)
        : panelPaper(i, total, quoteY, markH),
      starsSvg: starsSvg(filled, dark ? starDark : star),
      dividerSvg: dividerSvg(dark ? paper : ink, dark ? '0.2' : '0.16'),
      treatment: dark ? 'ink' : 'paper',
      quoteChars: qLen,
      quoteLines: fit.lines,
    });
  });

  // ---- intro / outro copy -------------------------------------------------
