}

// === n8n glue ===
const config = $('Config').first().json;
const data = $input.first().json;
const built = buildProject(config, data);
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs
// — including resolving the template's variables and expanding `iterate` into
// one scene per testimonial — so a failure here is a payload bug. Surface the
// field list instead of a generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to watch the
// exact compilation, then set dryRun to false in Config to go live. No sheet
// row is marked compiled on a dry run, so the next real run uses the same rows.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;
const guard = $('Music guard').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    rendered: false,
    videoUrl: null,
    source: d.meta.source,
    monthLabel: d.meta.monthLabel,
    quotes: d.meta.quoteCount,
    scenes: d.meta.sceneCount,
    starred: d.meta.starredCount,
    trimmedQuotes: d.meta.truncatedCount,
    videoSeconds: d.meta.totalSeconds,
    creditsRequired: d.creditsRequired,
    warnings: d.warnings,
    music: guard.musicUrl ? 'on' : ('off - ' + (guard.musicSkippedReason || 'no musicUrl')),
    authors: (d.meta.rows || []).map((r) => r.author),
    sheetRows: (d.meta.rows || []).map((r) => r.rowNumber),
    sheetUpdated: false,
    editorLink,
    draftId,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render for real.'
      : 'Set dryRun to false in Config to render this for real.',
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// One item per testimonial that made it into the film, each carrying the row
// the write-back should stamp. Every used row gets the same video URL, because
// they are all in the same compilation.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const rows = Array.isArray(build.meta.rows) ? build.meta.rows : [];
return rows.map((r, i) => ({
  json: {
    rowNumber: r.rowNumber,
    recordId: r.recordId,
    author: r.author,
    position: (i + 1) + ' / ' + rows.length,
    status: cfg.statusDoneValue,
    videoUrl: url,
    jobId: job.id,
  },
}));

// Final report for a live run. In sheet mode every row used by the
// compilation is already stamped by this point; in Airtable mode there is no
// row_number to match on, so the records are reported here and left untouched.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const guard = $('Music guard').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const source = String(cfg.source || 'sheet').toLowerCase();
const rows = Array.isArray(build.meta.rows) ? build.meta.rows : [];

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
